import scala.util.{Failure, Success, Try}
import scala.annotation.tailrec
import java.time.{LocalDate, LocalDateTime, ZonedDateTime}
import java.time.format.DateTimeFormatter
import scala.collection.mutable
import java.math.BigDecimal

// ============================================================================
// Enums and Data Structures
// ============================================================================

/**
 * Enumeration of different token types.
 */
sealed trait TokenType {
  def value: String
}

object TokenType {
  case object STRING extends TokenType { val value = "string" }
  case object NUMERIC extends TokenType { val value = "numeric" }
  case object TEMPORAL extends TokenType { val value = "temporal" }
  case object STRUCTURED extends TokenType { val value = "structured" }
  case object BINARY extends TokenType { val value = "binary" }
  case object NULL extends TokenType { val value = "null" }

  def fromString(s: String): Option[TokenType] = s match {
    case "string" => Some(STRING)
    case "numeric" => Some(NUMERIC)
    case "temporal" => Some(TEMPORAL)
    case "structured" => Some(STRUCTURED)
    case "binary" => Some(BINARY)
    case "null" => Some(NULL)
    case _ => None
  }
}

/**
 * Immutable token representation.
 */
case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  /**
   * Return new token with additional metadata.
   */
  def withMetadata(additionalMetadata: (String, Any)*): Token = {
    copy(metadata = metadata ++ additionalMetadata)
  }
}

// ============================================================================
// Type Classes and Abstractions
// ============================================================================

/**
 * Type class for types that can be converted to tokens.
 */
trait Tokenizable[-T] {
  def toToken(value: T): Token
}

/**
 * Type class for types that have a length.
 */
trait HasLength[T] {
  def length(value: T): Int
}

object Tokenizable {
  implicit object StringTokenizable extends Tokenizable[String] {
    def toToken(value: String): Token = Token(value, TokenType.STRING)
  }

  implicit object BytesTokenizable extends Tokenizable[Array[Byte]] {
    def toToken(value: Array[Byte]): Token = {
      val str = new String(value, "UTF-8")
      Token(str, TokenType.STRING, Map("encoding" -> "UTF-8"))
    }
  }

  implicit object IntTokenizable extends Tokenizable[Int] {
    def toToken(value: Int): Token = Token(value.toString, TokenType.NUMERIC)
  }

  implicit object LongTokenizable extends Tokenizable[Long] {
    def toToken(value: Long): Token = Token(value.toString, TokenType.NUMERIC)
  }

  implicit object DoubleTokenizable extends Tokenizable[Double] {
    def toToken(value: Double): Token = Token(value.toString, TokenType.NUMERIC)
  }

  implicit object BigDecimalTokenizable extends Tokenizable[BigDecimal] {
    def toToken(value: BigDecimal): Token = Token(value.toString, TokenType.NUMERIC)
  }

  implicit object LocalDateTokenizable extends Tokenizable[LocalDate] {
    def toToken(value: LocalDate): Token = {
      Token(value.format(DateTimeFormatter.ISO_LOCAL_DATE), TokenType.TEMPORAL)
    }
  }

  implicit object LocalDateTimeTokenizable extends Tokenizable[LocalDateTime] {
    def toToken(value: LocalDateTime): Token = {
      Token(value.format(DateTimeFormatter.ISO_LOCAL_DATE_TIME), TokenType.TEMPORAL)
    }
  }

  implicit object ZonedDateTimeTokenizable extends Tokenizable[ZonedDateTime] {
    def toToken(value: ZonedDateTime): Token = {
      Token(value.format(DateTimeFormatter.ISO_ZONED_DATE_TIME), TokenType.TEMPORAL)
    }
  }

  def apply[T](implicit ev: Tokenizable[T]): Tokenizable[T] = ev
}

// ============================================================================
// Abstract Base Tokenizer
// ============================================================================

/**
 * Abstract base tokenizer with generic input type.
 */
abstract class BaseTokenizer[T] {
  def tokenize(value: T): Token

  /**
   * Lazy tokenization of multiple values.
   */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

// ============================================================================
// Concrete Tokenizer Implementations
// ============================================================================

/**
 * Tokenizer for string and bytes types.
 */
case class StringTokenizer(
  encoding: String = "UTF-8",
  normalizer: String => String = identity
) extends BaseTokenizer[Any] {

  override def tokenize(value: Any): Token = value match {
    case bytes: Array[Byte] =>
      val strValue = new String(bytes, encoding)
      val normalized = normalizer(strValue)
      Token(normalized, TokenType.STRING)
    case str: String =>
      val normalized = normalizer(str)
      Token(normalized, TokenType.STRING)
    case null =>
      Token("NULL", TokenType.NULL)
    case other =>
      Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

/**
 * Tokenizer for numeric types with precision handling.
 */
case class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {

  override def tokenize(value: Any): Token = value match {
    case bd: BigDecimal =>
      val strValue = bd.setScale(precision, BigDecimal.ROUND_HALF_UP).toString
      Token(strValue, TokenType.NUMERIC, Map("originalType" -> "BigDecimal"))
    case d: Double if !d.isNaN && !d.isInfinity =>
      val strValue = f"$d%.${precision}f"
      Token(strValue, TokenType.NUMERIC, Map("originalType" -> "Double"))
    case f: Float if !f.isNaN && !f.isInfinity =>
      val strValue = f"$f%.${precision}f"
      Token(strValue, TokenType.NUMERIC, Map("originalType" -> "Float"))
    case n: Int =>
      Token(n.toString, TokenType.NUMERIC, Map("originalType" -> "Int"))
    case n: Long =>
      Token(n.toString, TokenType.NUMERIC, Map("originalType" -> "Long"))
    case other =>
      Token(other.toString, TokenType.NUMERIC, Map("originalType" -> other.getClass.getSimpleName))
  }
}

/**
 * Tokenizer for date/time types.
 */
case class TemporalTokenizer(
  formatStr: Option[String] = None
) extends BaseTokenizer[LocalDate | LocalDateTime | ZonedDateTime] {

  val isoFormat: DateTimeFormatter = DateTimeFormatter.ISO_LOCAL_DATE_TIME
  val dateFormat: DateTimeFormatter = DateTimeFormatter.ISO_LOCAL_DATE

  override def tokenize(value: LocalDate | LocalDateTime | ZonedDateTime): Token = value match {
    case dt: LocalDateTime =>
      val formatter = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(isoFormat)
      Token(dt.format(formatter), TokenType.TEMPORAL)
    case ld: LocalDate =>
      val formatter = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(dateFormat)
      Token(ld.format(formatter), TokenType.TEMPORAL)
    case zdt: ZonedDateTime =>
      val formatter = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(DateTimeFormatter.ISO_ZONED_DATE_TIME)
      Token(zdt.format(formatter), TokenType.TEMPORAL)
    case other =>
      Token(other.toString, TokenType.TEMPORAL)
  }
}

// ============================================================================
// Universal Tokenizer
// ============================================================================

/**
 * Tokenizer that handles multiple types using type classes.
 */
case class UniversalTokenizer() extends BaseTokenizer[Any] {

  override def tokenize(value: Any): Token = value match {
    case null => Token("NULL", TokenType.NULL)
    case token: Token => token
    case _ =>
      // Use type class to tokenize
      Tokenizable[Any].toToken(value)
  }
}

// ============================================================================
// Whitespace Tokenizer
// ============================================================================

/**
 * Tokenizer that splits text by whitespace.
 */
case class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {

  private val punctuation: Set[Char] = Set(',', '.', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def processToken(word: String, position: Int): Option[Token] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.filterNot(punctuation.contains)
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) {
      None
    } else {
      val finalValue = maxLength match {
        case Some(max) if processed.length > max => processed.take(max)
        case _ => processed
      }

      if (finalValue.isEmpty) None
      else Some(Token(finalValue, TokenType.STRING, Map("position" -> position, "original" -> word)))
    }
  }

  /**
   * Split text by whitespace and return list of tokens.
   */
  def tokenize(text: String): List[Token] = {
    text.split("\\s+").view.zipWithIndex.flatMap {
      case (word, idx) => processToken(word, idx)
    }.toList
  }

  /**
   * Split text by whitespace and return list of token strings.
   */
  def tokenizeToStrings(text: String): List[String] = {
    tokenize(text).map(_.value)
  }

  /**
   * Tokenize text and return tokens with character positions.
   */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    @tailrec
    def findPosition(searchText: String, target: String, from: Int, maxIterations: Int = 10000): Option[Int] = {
      if (maxIterations <= 0) None
      else {
        val idx = searchText.indexOf(target, from)
        if (idx >= 0) Some(idx)
        else if (from >= searchText.length) None
        else findPosition(searchText, target, from + 1, maxIterations - 1)
      }
    }

    val words = text.split("\\s+")
    val result = mutable.ListBuffer[(String, Int, Int)]()
    var currentPos = 0

    words.foreach { word =>
      val startOpt = findPosition(text, word, currentPos)
      startOpt.foreach { start =>
        val end = start + word.length
        processToken(word, result.size).foreach { _ =>
          result += ((word, start, end))
        }
        currentPos = end
      }
    }

    result.toList
  }

  /**
   * Return the number of tokens in the text.
   */
  def countTokens(text: String): Int = {
    tokenize(text).size
  }
}

