/**
 * Token registry for managing multiple tokenizers.
 */
class TokenRegistry[T] {
  private val registry: mutable.Map[String, Seq[Token]] = mutable.Map.empty
  private val handlers: mutable.ListBuffer[Token => Option[Token]] = mutable.ListBuffer.empty

  def register(key: String, tokens: Seq[Token]): Unit = {
    registry(key) = tokens
  }

  def addHandler(handler: Token => Option[Token]): Unit = {
    handlers += handler
  }

  def process(key: String): Seq[Token] = {
    registry.get(key).map { tokens =>
      tokens.flatMap { token =>
        handlers.toSeq.flatMap(_.apply(token)).headOption match {
          case Some(result) => Some(result)
          case None => Some(token)
        }
      }
    }.getOrElse(Seq.empty)
  }
}

